"""Opt-in recovery of a unique corner on both endpoint tangent extensions.

An almost opposing pair can yield a local circle at its two backward tangent
extensions and a remote circle with one contact far along a curved Street.
The old outward-only dispatch discards both and tries an S join that need not
exist. Prefer the unique double-extension circle only when there are multiple
certified candidates and no candidate on both outward spans. Original unique
circles and ambiguous outward sets are unchanged. Radius, tangency and complete
boundary/surface guards are retained; this policy is not a public asset change.
"""
import hashlib
import bpy

from . import curved_corner_nodes as c
from .curved_quad_fair_nodes import assign_group


def replace_saved(roots, *, reconcile_builder_sources=False):
    """Reconcile builder ID references only in a disposable asset export.

    A live-scene trial retains its old Python entry points. An exported shared
    asset must update those non-evaluated references through the same memo as
    the GN calls, or it also serializes a second, superseded set of recipes.
    """
    memo={};changes=[];visiting=set()

    def boundary(tree):
        result=tree.copy()
        result.name='Prochitecture Streets / Endpoint-extension corner / '+hashlib.sha256(tree.name.encode()).hexdigest()[:16]
        result.use_fake_user=False
        g=c.Graph.__new__(c.Graph);g.g=result;g.count=len(result.nodes);g.frame=None
        solver,=[n for n in result.nodes if n.label=='Native curve-offset tangency candidates']
        old={key:[link.to_socket for link in solver.outputs[key].links] for key in ('Candidates','Candidate Count')}
        raw=solver.outputs['Candidates'];count=c.V(g,solver.outputs['Candidate Count'])
        a,b=[c.named(g,'st_cc_s'+key) for key in ('a','b')]
        outward=c._select(g,raw,(1.-g.math('LESS_THAN',a,0.))*(1.-g.math('LESS_THAN',b,0.)))
        behind=c._select(g,raw,(1.-g.math('GREATER_THAN',a,0.))*(1.-g.math('GREATER_THAN',b,0.)))
        use=g.math('GREATER_THAN',count,1.5)*g.math('COMPARE',c._count(g,outward),0.)
        use*=g.math('COMPARE',c._count(g,behind),1.)
        selected=c.choose(g,use,behind,raw,'GEOMETRY')
        selected_count=c.choose(g,use,1,count,'INT')
        for key,value in (('Candidates',selected),('Candidate Count',selected_count)):
            for target in old[key]:g.bind(value,target)
        # Capture the decision inside the existing per-corner repeat zone.
        record,=[n for n in result.nodes if n.bl_idname=='GeometryNodeStoreNamedAttribute'
                 and n.inputs['Name'].default_value=='st_cj_candidate_count']
        targets=[link.to_socket for link in record.outputs['Geometry'].links]
        tagged=c._store(g,record.outputs['Geometry'],'st_cj_endpoint_extension_selected',use,'BOOLEAN')
        for target in targets:g.bind(tagged,target)
        result['st_endpoint_extension_corner_candidate']=1
        changes.append(dict(original=tree.name,replacement=result.name,
            rule='unique double-backward candidate, multiple total candidates, zero double-outward candidates',
            physical_guards_retained=True))
        return result

    def visit(tree):
        if tree in memo:return memo[tree]
        if tree in visiting:
            raise ValueError('Cycle in corner calls or builder references: '+tree.name)
        visiting.add(tree)
        if any(n.label=='Native curve-offset tangency candidates' for n in tree.nodes):
            fields={n.inputs['Name'].default_value for n in tree.nodes
                    if n.bl_idname=='GeometryNodeStoreNamedAttribute'}
            if not {'st_cj_extrapolated_continuation','st_cj_outward_candidate_count'}<=fields:
                raise ValueError('Endpoint recovery requires the existing outward dispatch: '+tree.name)
            result=boundary(tree)
        else:
            children=[(n.name,visit(n.node_tree)) for n in tree.nodes if n.type=='GROUP' and n.node_tree]
            children=[(name,child) for name,child in children if child!=tree.nodes[name].node_tree]
            references=[]
            if reconcile_builder_sources:
                references=[(key,visit(value)) for key,value in tree.items()
                            if isinstance(value,bpy.types.NodeTree)]
                references=[(key,value) for key,value in references if value!=tree[key]]
            result=tree.copy() if children or references else tree
            if children or references:result.use_fake_user=False
            for name,child in children:assign_group(result.nodes[name],child)
            for key,value in references:result[key]=value
        memo[tree]=result;visiting.remove(tree);return result
    result=[visit(root) for root in roots]
    if not changes:raise ValueError('No eligible saved boundary found')
    if reconcile_builder_sources:
        entries=[(old.name,old,new) for old,new in memo.items() if old!=new
                 and old.name.startswith('Prochitecture Streets / Cached original patch owner v2')]
        for name,old,new in entries:
            old.name='Prochitecture Streets / Before endpoint builder source / '+hashlib.sha256(name.encode()).hexdigest()[:16]
            new.name=name
            if new.name!=name:raise ValueError('Could not retain canonical builder name: '+name)
        changes[0]['reconciled_builder_entry_points']=[name for name,_,_ in entries]
    for previous,root in zip(roots,result):
        if root==previous:continue
        root['blosm_endpoint_extension_corner_candidate']=1
        if 'blosm_asset_reference' in root:del root['blosm_asset_reference']
    return result,changes
